1	// Cloudflare OAuth — "Connect Cloudflare" instead of pasting an API token.
2	//
3	// Plain server-side module (NO "use server") — imported by the OAuth routes, the
4	// server actions and the DNS helpers. Never bundled to the client; no token or
5	// secret is ever logged or returned to the browser.
6	//
7	// Nxeon is a server-side Next.js app, so we are a CONFIDENTIAL client: the
8	// Authorization Code flow with a client secret (client_secret_post), PLUS PKCE
9	// (S256) because Cloudflare advertises support for it and it costs us nothing.
10	// Cloudflare supports ONLY the authorization-code grant for third-party clients
11	// (no client-credentials / implicit / device), plus refresh_token for renewals.
12	//
13	// ---------------------------------------------------------------------------
14	// PROTOCOL CONSTANTS — the one block to correct if Cloudflare changes anything.
15	//
16	// CONFIRMED from Cloudflare docs + their live OIDC discovery document
17	// (https://dash.cloudflare.com/.well-known/openid-configuration, fetched
18	// 2026-07-25):
19	//   * authorize  https://dash.cloudflare.com/oauth2/auth
20	//   * token      https://dash.cloudflare.com/oauth2/token
21	//   * revoke     https://dash.cloudflare.com/oauth2/revoke
22	//   * grant_types_supported includes "authorization_code" and "refresh_token"
23	//   * token_endpoint_auth_methods_supported includes client_secret_post/basic
24	//   * code_challenge_methods_supported includes "S256"
25	//   * "offline_access" is a supported scope (that's what yields a refresh token)
26	//
27	// ASSUMED (could NOT be confirmed from public docs): the exact resource scope
28	// names for zone read + DNS edit. Cloudflare documents only that "OAuth scope
29	// names correspond to Cloudflare API token permission names" and that the full
30	// list is enumerable at `GET https://api.cloudflare.com/client/v4/oauth/scopes`
31	// — which requires an authenticated API token, so it can't be read from here.
32	// The API-token permissions we need are named "Zone Read" and "DNS Write"
33	// (Zone category), whose documented permission keys are `#zone:read` and
34	// `#dns_records:edit`; the default below is those minus the `#`, which is also
35	// the form Cloudflare's own first-party client (wrangler) sends (`zone:read`).
36	// If Cloudflare's client registration UI shows a different form (their docs
37	// example uses a dotted style, e.g. `workers-platform.read`), DO NOT edit code:
38	// set CLOUDFLARE_OAUTH_SCOPES in the env to the exact space-separated list
39	// shown when registering the client. Candidates, in order of likelihood:
40	//   1. "zone:read dns_records:edit offline_access"   (default below)
41	//   2. "zone.read dns.edit offline_access"
42	// We request the MINIMUM needed: read the customer's zones, write DNS records.
43	// ---------------------------------------------------------------------------
44	
45	import { db } from "./db";
46	import { encryptSecret, decryptSecret } from "./crypto-box";
47	import { SANDBOX } from "./sandbox";
48	import { createHash, randomBytes } from "node:crypto";
49	
50	export const CF_OAUTH_AUTHORIZE_URL =
51	  process.env.CLOUDFLARE_OAUTH_AUTHORIZE_URL ?? "https://dash.cloudflare.com/oauth2/auth";
52	export const CF_OAUTH_TOKEN_URL =
53	  process.env.CLOUDFLARE_OAUTH_TOKEN_URL ?? "https://dash.cloudflare.com/oauth2/token";
54	export const CF_OAUTH_REVOKE_URL =
55	  process.env.CLOUDFLARE_OAUTH_REVOKE_URL ?? "https://dash.cloudflare.com/oauth2/revoke";
56	
57	/** Space-separated scope list sent to /authorize. Env-overridable (see above). */
58	export const CF_OAUTH_SCOPES =
59	  process.env.CLOUDFLARE_OAUTH_SCOPES ?? "zone:read dns_records:edit offline_access";
60	
61	/** Human summary of the access we ask for, shown in the UI. */
62	export const CF_SCOPE_SUMMARY = "read your zones and edit DNS records";
63	
64	/** Redirect URI — must be registered verbatim on the Cloudflare OAuth client. */
65	export function cfRedirectUri(): string {
66	  const base = (process.env.APP_URL ?? "https://nxeon.cloud").replace(/\/$/, "");
67	  return `${base}/api/integrations/cloudflare/callback`;
68	}
69	
70	/**
71	 * Is the OAuth client registered in this environment? When false the UI hides
72	 * the "Connect Cloudflare" button and falls back to the paste-a-token path, so
73	 * nothing breaks before the owner registers the client in their dashboard.
74	 */
75	export function cloudflareOauthConfigured(): boolean {
76	  return Boolean(
77	    (process.env.CLOUDFLARE_OAUTH_CLIENT_ID ?? "").trim() &&
78	      (process.env.CLOUDFLARE_OAUTH_CLIENT_SECRET ?? "").trim(),
79	  );
80	}
81	
82	// ---- Stored credentials ----------------------------------------------------
83	
84	/**
85	 * OAuth credentials as stored (encrypted) in `User.cloudflareTokenEnc`.
86	 *
87	 * NO SCHEMA CHANGE: the existing column holds either
88	 *   - a JSON blob of this shape  → OAuth connection, or
89	 *   - a bare API-token string    → legacy pasted token (still fully supported).
90	 * `readStoredCloudflare` sniffs which one it is.
91	 */
92	export type CfOauthCreds = {
93	  accessToken: string;
94	  refreshToken?: string | null;
95	  /** Epoch ms when the access token expires (absent = unknown/never). */
96	  expiresAt?: number | null;
97	  scope?: string | null;
98	};
99	
100	export type StoredCloudflare =
101	  | { kind: "oauth"; creds: CfOauthCreds }
102	  | { kind: "token"; token: string }
103	  | null;
104	
105	/** Encrypt OAuth creds for storage in the existing column. */
106	export function packCreds(creds: CfOauthCreds): string {
107	  return encryptSecret(JSON.stringify({ v: 1, ...creds }));
108	}
109	
110	/**
111	 * Decrypt + classify whatever is in `User.cloudflareTokenEnc`. A value that
112	 * parses as a JSON object with an accessToken is an OAuth connection; anything
113	 * else non-empty is treated as a legacy pasted API token.
114	 */
115	export function readStoredCloudflare(enc: string | null | undefined): StoredCloudflare {
116	  const raw = decryptSecret(enc);
117	  if (!raw) return null;
118	  const trimmed = raw.trim();
119	  if (trimmed.startsWith("{")) {
120	    try {
121	      const parsed = JSON.parse(trimmed) as Partial<CfOauthCreds>;
122	      if (parsed && typeof parsed.accessToken === "string" && parsed.accessToken) {
123	        return {
124	          kind: "oauth",
125	          creds: {
126	            accessToken: parsed.accessToken,
127	            refreshToken: parsed.refreshToken ?? null,
128	            expiresAt: typeof parsed.expiresAt === "number" ? parsed.expiresAt : null,
129	            scope: parsed.scope ?? null,
130	          },
131	        };
132	      }
133	    } catch {
134	      // Not JSON after all — fall through to the legacy-token branch.
135	    }
136	    return null;
137	  }
138	  return { kind: "token", token: trimmed };
139	}
140	
141	// ---- Authorization request -------------------------------------------------
142	
143	/** Random URL-safe string for `state` / the PKCE verifier. */
144	export function randomUrlSafe(bytes = 32): string {
145	  return randomBytes(bytes).toString("base64url");
146	}
147	
148	/** S256 code challenge for a PKCE verifier. */
149	export function pkceChallenge(verifier: string): string {
150	  return createHash("sha256").update(verifier).digest("base64url");
151	}
152	
153	/** Build the Cloudflare consent URL for this connection attempt. */
154	export function cfAuthorizeUrl(opts: { state: string; codeChallenge: string }): string {
155	  const url = new URL(CF_OAUTH_AUTHORIZE_URL);
156	  url.searchParams.set("response_type", "code");
157	  url.searchParams.set("client_id", (process.env.CLOUDFLARE_OAUTH_CLIENT_ID ?? "").trim());
158	  url.searchParams.set("redirect_uri", cfRedirectUri());
159	  // Cloudflare grants the permissions the OAuth CLIENT was registered with; it
160	  // does NOT accept them as requestable authorize-time scopes. Probing the live
161	  // endpoint returns `invalid_scope` — "The OAuth 2.0 Client is not allowed to
162	  // request scope 'X'" — for every value tried, including `offline_access` and
163	  // `openid`, while omitting the parameter entirely succeeds (302 to consent).
164	  // So send `scope` only if an operator explicitly sets CLOUDFLARE_OAUTH_SCOPES.
165	  if (CF_OAUTH_SCOPES.trim()) url.searchParams.set("scope", CF_OAUTH_SCOPES.trim());
166	  url.searchParams.set("state", opts.state);
167	  url.searchParams.set("code_challenge", opts.codeChallenge);
168	  url.searchParams.set("code_challenge_method", "S256");
169	  return url.toString();
170	}
171	
172	// ---- Token endpoint --------------------------------------------------------
173	
174	type TokenResponse = {
175	  access_token?: string;
176	  refresh_token?: string;
177	  expires_in?: number;
178	  scope?: string;
179	  token_type?: string;
180	  error?: string;
181	  error_description?: string;
182	};
183	
184	/**
185	 * POST to the token endpoint with client_secret_post auth. Returns creds or a
186	 * short error string. NEVER includes the client secret or any token in the
187	 * error text (Cloudflare's `error_description` is safe — it describes the grant).
188	 */
189	async function tokenRequest(body: Record<string, string>): Promise<{ creds?: CfOauthCreds; error?: string }> {
190	  const clientId = (process.env.CLOUDFLARE_OAUTH_CLIENT_ID ?? "").trim();
191	  const clientSecret = (process.env.CLOUDFLARE_OAUTH_CLIENT_SECRET ?? "").trim();
192	
193	  // Token-endpoint auth method must match how the OAuth client was REGISTERED in
194	  // the Cloudflare dashboard. Ours is registered as "Client Secret Basic", so we
195	  // send HTTP Basic by default; set CLOUDFLARE_OAUTH_TOKEN_AUTH=post to switch to
196	  // client_secret_post (credentials in the form body) without a code change.
197	  const useBasic = (process.env.CLOUDFLARE_OAUTH_TOKEN_AUTH ?? "basic").toLowerCase() !== "post";
198	
199	  const params = new URLSearchParams({
200	    ...body,
201	    client_id: clientId,
202	    ...(useBasic ? {} : { client_secret: clientSecret }),
203	  });
204	
205	  const headers: Record<string, string> = {
206	    "Content-Type": "application/x-www-form-urlencoded",
207	    Accept: "application/json",
208	  };
209	  if (useBasic) {
210	    // RFC 6749 §2.3.1 — client_id:client_secret, base64, in the Authorization header.
211	    headers.Authorization = `Basic ${Buffer.from(`${clientId}:${clientSecret}`).toString("base64")}`;
212	  }
213	
214	  let res: Response;
215	  try {
216	    res = await fetch(CF_OAUTH_TOKEN_URL, {
217	      method: "POST",
218	      headers,
219	      body: params.toString(),
220	      cache: "no-store",
221	    });
222	  } catch {
223	    return { error: "Couldn't reach Cloudflare to finish connecting. Try again shortly." };
224	  }
225	
226	  let parsed: TokenResponse | null = null;
227	  try {
228	    parsed = (await res.json()) as TokenResponse;
229	  } catch {
230	    parsed = null;
231	  }
232	
233	  if (!res.ok || !parsed?.access_token) {
234	    const detail = parsed?.error_description || parsed?.error || `HTTP ${res.status}`;
235	    return { error: `Cloudflare rejected the connection (${String(detail).slice(0, 160)}).` };
236	  }
237	
238	  const expiresIn = typeof parsed.expires_in === "number" ? parsed.expires_in : null;
239	  return {
240	    creds: {
241	      accessToken: parsed.access_token,
242	      refreshToken: parsed.refresh_token ?? null,
243	      expiresAt: expiresIn ? Date.now() + expiresIn * 1000 : null,
244	      scope: parsed.scope ?? CF_OAUTH_SCOPES,
245	    },
246	  };
247	}
248	
249	/** Exchange an authorization code (with the PKCE verifier) for credentials. */
250	export async function cfExchangeCode(opts: {
251	  code: string;
252	  codeVerifier: string;
253	}): Promise<{ creds?: CfOauthCreds; error?: string }> {
254	  return tokenRequest({
255	    grant_type: "authorization_code",
256	    code: opts.code,
257	    redirect_uri: cfRedirectUri(),
258	    code_verifier: opts.codeVerifier,
259	  });
260	}
261	
262	/** Trade a refresh token for a fresh access token. */
263	export async function cfRefresh(refreshToken: string): Promise<{ creds?: CfOauthCreds; error?: string }> {
264	  return tokenRequest({ grant_type: "refresh_token", refresh_token: refreshToken });
265	}
266	
267	/**
268	 * Best-effort revoke at Cloudflare so disconnecting here also drops their side.
269	 * Never throws and never blocks the local disconnect.
270	 */
271	export async function cfRevoke(token: string): Promise<void> {
272	  if (SANDBOX || !cloudflareOauthConfigured()) return;
273	  try {
274	    await fetch(CF_OAUTH_REVOKE_URL, {
275	      method: "POST",
276	      headers: { "Content-Type": "application/x-www-form-urlencoded" },
277	      body: new URLSearchParams({
278	        token,
279	        client_id: (process.env.CLOUDFLARE_OAUTH_CLIENT_ID ?? "").trim(),
280	        client_secret: (process.env.CLOUDFLARE_OAUTH_CLIENT_SECRET ?? "").trim(),
281	      }).toString(),
282	      cache: "no-store",
283	    });
284	  } catch {
285	    // Local disconnect is authoritative for us — ignore a failed remote revoke.
286	  }
287	}
288	
289	// ---- The accessor every Cloudflare call goes through -----------------------
290	
291	/** Friendly copy for the two "we can't act" states, reused by every surface. */
292	export const CF_NOT_CONNECTED =
293	  "Connect Cloudflare first — then we can create the DNS record for you. You can connect on this page or in Settings.";
294	export const CF_RECONNECT =
295	  "Your Cloudflare connection has expired. Reconnect Cloudflare in Settings and try again.";
296	
297	/** Refresh a little early so a long request can't straddle the expiry. */
298	const REFRESH_SKEW_MS = 90_000;
299	
300	/**
301	 * Resolve a usable bearer token for the Cloudflare v4 API from whatever the user
302	 * has connected. Handles both shapes:
303	 *   - legacy pasted API token → returned as-is (they don't expire on a clock),
304	 *   - OAuth creds → refreshed via the refresh token when expired/near-expiry,
305	 *     with the new blob re-encrypted back into `User.cloudflareTokenEnc`.
306	 *
307	 * Returns `{ error }` (never throws) for "nothing connected" and for a refresh
308	 * failure, so callers surface a friendly reconnect prompt instead of crashing.
309	 * `lib/cloudflare-dns.ts` keeps its per-call token signature — we just feed it
310	 * whatever this returns.
311	 */
312	export async function resolveCloudflareToken(user: {
313	  id: string;
314	  cloudflareTokenEnc: string | null;
315	}): Promise<{ token?: string; error?: string; needsReconnect?: boolean }> {
316	  const stored = readStoredCloudflare(user.cloudflareTokenEnc);
317	  if (!stored) return { error: CF_NOT_CONNECTED };
318	  if (stored.kind === "token") return { token: stored.token };
319	
320	  const { creds } = stored;
321	  const expired =
322	    typeof creds.expiresAt === "number" && creds.expiresAt > 0
323	      ? Date.now() > creds.expiresAt - REFRESH_SKEW_MS
324	      : false;
325	
326	  if (!expired) return { token: creds.accessToken };
327	
328	  if (SANDBOX) {
329	    // Staging never contacts Cloudflare; keep the synthetic connection usable.
330	    return { token: creds.accessToken };
331	  }
332	  if (!creds.refreshToken) return { error: CF_RECONNECT, needsReconnect: true };
333	
334	  const refreshed = await cfRefresh(creds.refreshToken);
335	  if (!refreshed.creds) {
336	    console.warn("[cloudflare-oauth] refresh failed for user", user.id);
337	    return { error: CF_RECONNECT, needsReconnect: true };
338	  }
339	
340	  const merged: CfOauthCreds = {
341	    ...refreshed.creds,
342	    // Cloudflare may omit a rotated refresh token — keep the existing one then.
343	    refreshToken: refreshed.creds.refreshToken ?? creds.refreshToken,
344	  };
345	  await db.user
346	    .update({ where: { id: user.id }, data: { cloudflareTokenEnc: packCreds(merged) } })
347	    .catch(() => {
348	      // A failed persist is survivable: this request still uses the new token.
349	    });
350	
351	  return { token: merged.accessToken };
352	}
