1	import { NextRequest, NextResponse } from "next/server";
2	import { requireUser } from "@/lib/auth";
3	import { checkRateLimit } from "@/lib/rate-limit";
4	import { SANDBOX } from "@/lib/sandbox";
5	import {
6	  cfAuthorizeUrl,
7	  cloudflareOauthConfigured,
8	  packCreds,
9	  pkceChallenge,
10	  randomUrlSafe,
11	} from "@/lib/cloudflare-oauth";
12	import { parseIntent, safeNext, withResult } from "@/lib/cloudflare-connect-intent";
13	import { db } from "@/lib/db";
14	import { runConnectIntent } from "@/lib/cloudflare-intent-run";
15	
16	export const dynamic = "force-dynamic";
17	
18	const base = () => (process.env.APP_URL ?? "").replace(/\/$/, "");
19	
20	/**
21	 * Step 1 of "Connect Cloudflare": start the Authorization Code flow.
22	 *
23	 * Requires a signed-in user, mints a CSRF `state` + PKCE verifier (S256) and
24	 * stashes them — with the intent and the return path — in a short-lived httpOnly
25	 * cookie, then redirects to Cloudflare's consent screen. Nothing sensitive rides
26	 * in the URL; the cookie is the only thing the callback trusts.
27	 */
28	export async function GET(req: NextRequest) {
29	  let user;
30	  try {
31	    user = await requireUser();
32	  } catch {
33	    return NextResponse.redirect(`${base()}/login`);
34	  }
35	
36	  const sp = req.nextUrl.searchParams;
37	  const intent = parseIntent({ intent: sp.get("intent"), id: sp.get("id"), host: sp.get("host") });
38	  const next = safeNext(sp.get("next"));
39	
40	  const rl = checkRateLimit(`cf-oauth-start:${user.id}`, { max: 10, windowMs: 60_000 });
41	  if (!rl.ok) {
42	    return NextResponse.redirect(
43	      `${base()}${withResult(next, { cf: "error", cfmsg: `Too many attempts — try again in ${rl.retryAfterSec}s.` })}`,
44	    );
45	  }
46	
47	  // SANDBOX: never leave the app. Store a synthetic connection and run the
48	  // auto-add straight away so staging exercises the whole "connect → records
49	  // added" path without touching Cloudflare.
50	  if (SANDBOX) {
51	    await db.user.update({
52	      where: { id: user.id },
53	      data: {
54	        cloudflareTokenEnc: packCreds({
55	          accessToken: `sandbox-${randomUrlSafe(12)}`,
56	          refreshToken: `sandbox-${randomUrlSafe(12)}`,
57	          expiresAt: Date.now() + 3600_000,
58	          scope: "sandbox",
59	        }),
60	      },
61	    });
62	    await db.auditLog
63	      .create({ data: { userId: user.id, action: "cloudflare.connect", detail: "OAuth (sandbox)" } })
64	      .catch(() => {});
65	    const outcome = await runConnectIntent(intent);
66	    return NextResponse.redirect(`${base()}${withResult(next, { cf: "connected", ...outcome.params })}`);
67	  }
68	
69	  if (!cloudflareOauthConfigured()) {
70	    return NextResponse.redirect(
71	      `${base()}${withResult(next, {
72	        cf: "error",
73	        cfmsg: "Cloudflare sign-in isn't set up on this server yet — paste an API token instead.",
74	      })}`,
75	    );
76	  }
77	
78	  const state = randomUrlSafe(24);
79	  const verifier = randomUrlSafe(32);
80	  const authUrl = cfAuthorizeUrl({ state, codeChallenge: pkceChallenge(verifier) });
81	
82	  const res = NextResponse.redirect(authUrl);
83	  res.cookies.set({
84	    name: "nx_cf_oauth",
85	    value: JSON.stringify({ state, verifier, next, intent, uid: user.id }),
86	    httpOnly: true,
87	    sameSite: "lax", // must survive the top-level redirect back from Cloudflare
88	    secure: (process.env.APP_URL ?? "").startsWith("https://"),
89	    path: "/api/integrations/cloudflare",
90	    maxAge: 600, // 10 minutes to complete consent
91	  });
92	  return res;
93	}
94

1	import { NextRequest, NextResponse } from "next/server";
2	import { requireUser } from "@/lib/auth";
3	import { db } from "@/lib/db";
4	import { cfExchangeCode, packCreds } from "@/lib/cloudflare-oauth";
5	import { parseIntent, safeNext, withResult, type CfConnectIntent } from "@/lib/cloudflare-connect-intent";
6	import { runConnectIntent } from "@/lib/cloudflare-intent-run";
7	
8	export const dynamic = "force-dynamic";
9	
10	const base = () => (process.env.APP_URL ?? "").replace(/\/$/, "");
11	
12	type Stash = { state?: string; verifier?: string; next?: string; intent?: unknown; uid?: string };
13	
14	/** Clear the one-shot OAuth cookie on every exit path. */
15	function finish(res: NextResponse): NextResponse {
16	  res.cookies.set({
17	    name: "nx_cf_oauth",
18	    value: "",
19	    httpOnly: true,
20	    path: "/api/integrations/cloudflare",
21	    maxAge: 0,
22	  });
23	  return res;
24	}
25	
26	/**
27	 * Step 2 of "Connect Cloudflare": the OAuth redirect target.
28	 *
29	 * Verifies the CSRF `state` against the httpOnly cookie, exchanges the code (with
30	 * the PKCE verifier) for credentials, stores them encrypted in the existing
31	 * `User.cloudflareTokenEnc` column, then immediately runs the action the customer
32	 * started — so they land back on their page with the DNS records already
33	 * published. No token is ever logged or put in a URL.
34	 */
35	export async function GET(req: NextRequest) {
36	  let user;
37	  try {
38	    user = await requireUser();
39	  } catch {
40	    return finish(NextResponse.redirect(`${base()}/login`));
41	  }
42	
43	  const raw = req.cookies.get("nx_cf_oauth")?.value;
44	  let stash: Stash = {};
45	  try {
46	    stash = raw ? (JSON.parse(raw) as Stash) : {};
47	  } catch {
48	    stash = {};
49	  }
50	
51	  const next = safeNext(stash.next);
52	  const fail = (msg: string) =>
53	    finish(NextResponse.redirect(`${base()}${withResult(next, { cf: "error", cfmsg: msg })}`));
54	
55	  const sp = req.nextUrl.searchParams;
56	
57	  // The customer declined on Cloudflare's consent screen (or Cloudflare errored).
58	  const oauthError = sp.get("error");
59	  if (oauthError) {
60	    return fail(
61	      oauthError === "access_denied"
62	        ? "Cloudflare connection cancelled."
63	        : `Cloudflare returned an error (${oauthError.slice(0, 60)}).`,
64	    );
65	  }
66	
67	  // CSRF: the state must match the cookie minted by /start for THIS user.
68	  const state = sp.get("state") ?? "";
69	  if (!stash.state || !stash.verifier || !state || state !== stash.state) {
70	    return fail("That Cloudflare sign-in link expired or didn't match. Please try connecting again.");
71	  }
72	  if (stash.uid && stash.uid !== user.id) {
73	    return fail("That Cloudflare sign-in was started by a different account. Please try again.");
74	  }
75	
76	  const code = sp.get("code") ?? "";
77	  if (!code) return fail("Cloudflare didn't return an authorization code. Please try connecting again.");
78	
79	  const exchanged = await cfExchangeCode({ code, codeVerifier: stash.verifier });
80	  if (!exchanged.creds) {
81	    return fail(exchanged.error ?? "Couldn't complete the Cloudflare connection. Please try again.");
82	  }
83	
84	  await db.user.update({
85	    where: { id: user.id },
86	    data: { cloudflareTokenEnc: packCreds(exchanged.creds) },
87	  });
88	  await db.auditLog
89	    .create({ data: { userId: user.id, action: "cloudflare.connect", detail: "OAuth authorised" } })
90	    .catch(() => {});
91	
92	  // "Connect → records added": finish the job they clicked from, with no extra step.
93	  const intent: CfConnectIntent =
94	    stash.intent && typeof stash.intent === "object"
95	      ? parseIntent({
96	          intent: (stash.intent as { kind?: string }).kind ?? null,
97	          id: (stash.intent as { id?: string }).id ?? null,
98	          host: (stash.intent as { host?: string }).host ?? null,
99	        })
