17	/** Trim a message to something safe to carry in a redirect query string. */
18	function msg(s: string): string {
19	  return s.replace(/\s+/g, " ").trim().slice(0, 220);
20	}
21	
22	/**
23	 * Execute the post-connect action for an intent. Never throws — any failure
24	 * becomes a `cfdns=error` flag with a friendly message, so the customer always
25	 * lands back on their page with an explanation rather than a stack trace.
26	 */
27	export async function runConnectIntent(intent: CfConnectIntent): Promise<IntentOutcome> {
28	  try {
29	    switch (intent.kind) {
30	      case "email": {
31	        const res = await autoCreateEmailDns(intent.id);
32	        if (res.error) return { params: { cfdns: "error", cfmsg: msg(res.error) } };
33	        const n = res.created?.length ?? 0;
34	        return {
35	          params: {
36	            cfdns: "ok",
37	            cfmsg: msg(`Created ${n} mail DNS record${n === 1 ? "" : "s"} in Cloudflare.`),
38	          },
39	        };
40	      }
41	      case "website": {
42	        const res = await pointWebsiteDns(intent.id);
43	        if (!res.ok) return { params: { cfdns: "error", cfmsg: msg(res.error) } };
44	        return { params: { cfdns: "ok", cfmsg: msg(res.message) } };
45	      }
46	      case "migration": {
47	        if (!intent.host) return { params: {} };
48	        const res = await pointMigrationDns(intent.id, intent.host);
49	        if (!res.ok) return { params: { cfdns: "error", cfmsg: msg(res.error) } };
50	        return { params: { cfdns: "ok", cfmsg: msg(res.message) } };
51	      }
52	      default:
53	        return { params: {} };
54	    }
55	  } catch {
56	    return {
57	      params: {
58	        cfdns: "error",
59	        cfmsg: "Cloudflare is connected, but we couldn't add the record automatically — try the button again.",
60	      },
61	    };
62	  }
63	}
