1	// What the customer was doing when they clicked "Connect Cloudflare".
2	//
3	// Plain server-side module shared by the OAuth start/callback routes and the
4	// client button. The intent rides in an httpOnly cookie (NOT the URL) alongside
5	// the CSRF `state` and the PKCE verifier, so the callback can finish the job the
6	// customer actually asked for — "log in with Cloudflare → records added", no
7	// extra clicks — and land them back on the page they started from.
8	//
9	// Everything here is validated: the callback re-checks ownership through the
10	// normal action paths before touching DNS, and `next` is forced to a relative
11	// /dashboard path so the flow can never be turned into an open redirect.
12	
13	export type CfConnectIntent =
14	  | { kind: "settings" }
15	  /** Business Email external-domain DNS for an EmailSubscription. */
16	  | { kind: "email"; id: string }
17	  /** Point a control-panel Website's hostname at its server. */
18	  | { kind: "website"; id: string }
19	  /** Post-migration: point one hostname at the migration's target server. */
20	  | { kind: "migration"; id: string; host?: string };
21	
22	const KINDS = ["settings", "email", "website", "migration"] as const;
23	
24	/** cuid-ish id guard — ids only ever come from our own rows. */
25	const ID_RE = /^[A-Za-z0-9_-]{6,64}$/;
26	
27	/**
28	 * Build an intent from raw query params. Anything unrecognised collapses to
29	 * `{ kind: "settings" }` (connect only, no auto-action) rather than erroring.
30	 */
31	export function parseIntent(params: {
32	  intent?: string | null;
33	  id?: string | null;
34	  host?: string | null;
35	}): CfConnectIntent {
36	  const kind = String(params.intent ?? "").trim();
37	  const id = String(params.id ?? "").trim();
38	  if (!(KINDS as readonly string[]).includes(kind)) return { kind: "settings" };
39	  if (kind === "settings") return { kind: "settings" };
40	  if (!ID_RE.test(id)) return { kind: "settings" };
41	  if (kind === "migration") {
42	    const host = String(params.host ?? "").trim().toLowerCase();
43	    return { kind: "migration", id, ...(host ? { host } : {}) };
44	  }
45	  return { kind: kind as "email" | "website", id };
46	}
47	
48	/**
49	 * Force a return path to a safe, same-origin dashboard route. Rejects absolute
50	 * URLs, protocol-relative paths and anything outside /dashboard.
51	 */
52	export function safeNext(next: string | null | undefined, fallback = "/dashboard/settings"): string {
53	  const raw = String(next ?? "").trim();
54	  if (!raw.startsWith("/") || raw.startsWith("//")) return fallback;
55	  if (!/^\/dashboard(\/|$|\?)/.test(raw)) return fallback;
56	  if (raw.includes("\\") || raw.includes("\n")) return fallback;
57	  return raw.slice(0, 300);
58	}
59	
60	/** Append our result flags to a dashboard path, preserving any existing query. */
61	export function withResult(next: string, params: Record<string, string>): string {
62	  const [path, query = ""] = next.split("?");
63	  const sp = new URLSearchParams(query);
64	  for (const [k, v] of Object.entries(params)) sp.set(k, v);
65	  const qs = sp.toString();
66	  return qs ? `${path}?${qs}` : path;
67	}
