124	/**
125	 * The exact redirect URI that must be registered on the Cloudflare OAuth client.
126	 * Surfaced in Settings only when OAuth isn't configured yet, so the operator can
127	 * see what to register. Contains no secrets.
128	 */
129	export async function cloudflareRedirectUri(): Promise<string> {
130	  await requireUser();
131	  return cfRedirectUri();
132	}
