38	 * lands the customer back on their page. Reads them from the URL on mount (no
39	 * useSearchParams, so no Suspense boundary needed) and tidies the URL afterwards.
40	 */
41	export function CloudflareResultBanner() {
42	  const [msg, setMsg] = useState<{ tone: "ok" | "error"; text: string } | null>(null);
43	
44	  useEffect(() => {
45	    const sp = new URLSearchParams(window.location.search);
46	    const cf = sp.get("cf");
47	    const cfdns = sp.get("cfdns");
48	    const detail = sp.get("cfmsg");
49	    if (!cf && !cfdns) return;
50	
51	    if (cf === "error") {
52	      setMsg({ tone: "error", text: detail || "Couldn't connect Cloudflare." });
53	    } else if (cfdns === "error") {
