65	    ["cf", "cfdns", "cfmsg"].forEach((k) => sp.delete(k));
66	    const qs = sp.toString();
67	    window.history.replaceState({}, "", `${window.location.pathname}${qs ? `?${qs}` : ""}`);
68	  }, []);
69	
70	  if (!msg) return null;
71	  return (
72	    <div
73	      className={`mb-4 rounded-xl border px-3 py-2 text-sm ${
74	        msg.tone === "ok"
75	          ? "border-emerald-500/30 bg-emerald-500/10 text-emerald-300"
76	          : "border-amber-500/30 bg-amber-500/10 text-amber-200"
77	      }`}
