84	/**
85	 * Connect state + connect controls. When connected it simply renders `children`
86	 * (the surface's own action, e.g. "Point DNS at this server"); when not, it shows
87	 * the Connect button and the advanced token fallback.
88	 */
89	export function CloudflareConnect({
90	  intent,
91	  id,
92	  host,
93	  next,
94	  connectedHint,
95	  onConnected,
96	  what,
97	  children,
98	  compact,
99	}: {
100	  intent: CfIntentKind;
101	  id?: string;
102	  host?: string;
103	  /** Dashboard path to return to after consent. */
104	  next: string;
105	  /** Optional first-paint value so the panel doesn't flicker. */
106	  connectedHint?: boolean;
107	  onConnected?: () => void;
108	  /** What we'll do once connected, e.g. "create these mail records". */
109	  what?: string;
110	  children?: ReactNode;
111	  compact?: boolean;
112	}) {
113	  const [status, setStatus] = useState<CloudflareStatus | null>(null);
114	  const [token, setToken] = useState("");
115	  const [error, setError] = useState<string | null>(null);
116	  const [saving, startSave] = useTransition();
117	
118	  useEffect(() => {
119	    let cancelled = false;
120	    getCloudflareStatus()
121	      .then((s) => {
122	        if (!cancelled) setStatus(s);
123	      })
124	      .catch(() => {
125	        /* leave the hint in place */
126	      });
127	    return () => {
128	      cancelled = true;
129	    };
130	  }, []);
131	
132	  const connected = status?.connected ?? connectedHint ?? false;
133	  const oauthAvailable = status?.oauthAvailable ?? true;
