71	export type PointDnsOk = {
72	  ok: true;
73	  hostname: string;
74	  ip: string;
75	  zone: string;
76	  action: "created" | "updated";
77	  /** True when the record was faked because we're running in sandbox mode. */
78	  simulated: boolean;
79	};
80	export type PointDnsResult = PointDnsOk | { ok: false; error: string };
81	
82	/**
83	 * Upsert `hostname` -> `ip` as a DNS-only A record in the customer's Cloudflare
84	 * zone. Callers MUST have already authenticated the user and confirmed they own
85	 * both the hostname's record (website / migration) and the target server.
86	 *
87	 * The caller passes the user row; `resolveCloudflareToken` turns whatever they
88	 * connected (OAuth credentials — refreshed here if stale — or a legacy pasted
89	 * API token) into a bearer token, so no caller ever handles the plaintext.
90	 * Returns a friendly `{ ok:false, error }` for every expected failure (nothing
91	 * connected, expired connection, bad hostname, zone not in the account, missing
92	 * DNS→Edit) and never throws CloudflareError at the caller.
93	 *
94	 * In SANDBOX mode nothing is sent to Cloudflare — we return a synthetic success
95	 * so staging can exercise the whole flow end to end.
96	 */
97	export async function pointHostnameToIp(opts: {
98	  user: { id: string; cloudflareTokenEnc: string | null };
99	  hostname: string;
100	  ip: string | null | undefined;
101	}): Promise<PointDnsResult> {
102	  const hostname = cleanHostname(opts.hostname);
103	  if (!hostname) {
104	    return { ok: false, error: "Enter a valid domain or subdomain (e.g. example.com)." };
105	  }
106	
107	  const ip = String(opts.ip ?? "").trim();
108	  if (!isIpv4(ip)) {
109	    return {
110	      ok: false,
111	      error: "This server doesn't have a public IPv4 address yet — try again once it's finished provisioning.",
112	    };
113	  }
114	
115	  const resolved = await resolveCloudflareToken(opts.user);
116	  const token = resolved.token;
117	  if (!token) return { ok: false, error: resolved.error ?? "Connect Cloudflare first." };
118	
119	  if (SANDBOX) {
120	    // Staging never talks to Cloudflare. Report the record we WOULD have written.
121	    const labels = hostname.split(".");
122	    return {
123	      ok: true,
124	      hostname,
125	      ip,
126	      zone: labels.slice(-2).join("."),
127	      action: "created",
128	      simulated: true,
129	    };
130	  }
131	
132	  // Find which zone in the account owns this hostname (most specific first).
133	  let zoneId: string | null = null;
134	  let zone = "";
135	  try {
136	    for (const candidate of zoneCandidates(hostname)) {
137	      const found = await cfFindZoneId(token, candidate);
138	      if (found) {
139	        zoneId = found;
140	        zone = candidate;
141	        break;
142	      }
143	    }
144	  } catch (e) {
145	    if (e instanceof CloudflareError) {
146	      return { ok: false, error: `Cloudflare error: ${e.message}` };
147	    }
148	    throw e;
149	  }
150	  if (!zoneId) {
151	    return {
152	      ok: false,
153	      error: `No Cloudflare zone found for ${hostname}. Add the domain to Cloudflare first, or check the Cloudflare account you connected holds this zone.`,
154	    };
155	  }
156	
157	  try {
158	    const [result] = await cfUpsertRecords(token, zoneId, [
159	      // proxied:false — DNS-only, so the name resolves straight to the server and
160	      // Let's Encrypt HTTP-01 validation can reach certbot on it.
161	      { type: "A", name: hostname, content: ip, proxied: false },
162	    ]);
163	    return {
164	      ok: true,
165	      hostname,
166	      ip,
167	      zone,
168	      action: result?.action ?? "created",
169	      simulated: false,
170	    };
171	  } catch (e) {
172	    if (e instanceof CloudflareError) {
173	      return {
174	        ok: false,
175	        error: `Couldn't write the DNS record: ${e.message}. Check the connected Cloudflare account can edit DNS for ${zone}.`,
176	      };
177	    }
178	    throw e;
179	  }
180	}
