167	    return { error: "That transfer is already being submitted — give it a moment before retrying." };
168	  }
169	
170	  try {
171	    const existing = await db.domain.findUnique({ where: { name: domain } });
172	    if (existing) {
173	      if (existing.userId !== user.id) return { error: "This domain is already managed by another account." };
174	      if (existing.status === "TRANSFER_PENDING") {
175	        return { error: "A transfer for this domain is already in progress — you have not been charged twice." };
176	      }
177	      if (!RETRYABLE.includes(existing.status as (typeof RETRYABLE)[number])) {
178	        return { error: `${domain} is already on your account (status: ${existing.status.toLowerCase()}).` };
179	      }
180	    }
181	
182	    // Re-quote server-side. The wizard's number is a display; this is the price.
183	    let check: TransferCheck;
184	    try {
185	      check = await checkTransfer(domain);
186	    } catch (e) {
187	      return { error: errMsg(e) };
188	    }
189	    if (!check.transferable || check.priceCents === null || check.costCents === null) {
190	      return { error: check.reason ?? "This domain can't be transferred in right now." };
191	    }
192	    const totalCents = transferChargeCents(check.priceCents); // retail — what we charge
193	    const registrarCostCents = check.costCents; // cost — what we tell name.com to spend
194	
195	    if (expectedCents !== totalCents) {
196	      return {
197	        error:
198	          `The registrar's price changed while you were filling this in — it's now $${(totalCents / 100).toFixed(2)}. ` +
