268	          data: invoiceCreateData({
269	            userId: user.id,
270	            description: transferChargeDescription(domain),
271	            status: "PAID",
272	            lineItems: [
273	              {
274	                description: `Domain transfer in — ${domain} (adds 1 year to the registration)`,
275	                qty: 1,
276	                unitCents: totalCents,
277	                amountCents: totalCents,
278	              },
279	            ],
280	          }),
281	        });
