292	      } catch {
293	        /* registrar refused the cancel — ops has to unwind it manually */
294	      }
295	      await db.auditLog
296	        .create({
297	          data: {
298	            userId: user.id,
299	            action: "domain.transfer_in.uncharged",
300	            detail: `${domain}: submitted but not charged (${errMsg(e)}) — cancelled=${cancelled}`.slice(0, 500),
301	          },
302	        })
